120	// settingsHintOnce ensures the settings commit hint prints at most once per process.
121	var settingsHintOnce sync.Once
122	
123	// printSettingsCommitHint prints a hint after a successful checkpoint remote push
124	// when the committed .entire/settings.json does not contain a checkpoint_remote config.
125	// entire.io discovers the external checkpoint repo by reading the committed project
126	// settings, so the checkpoint_remote must be present in HEAD:.entire/settings.json
127	// (not just in settings.local.json or uncommitted local changes).
128	// Uses sync.Once to avoid duplicates when multiple branches/refs are pushed in a
129	// single pre-push invocation.
130	func printSettingsCommitHint(ctx context.Context, target string) {
131		if !isURL(target) {
132			return
133		}
134		settingsHintOnce.Do(func() {
135			if isCheckpointRemoteCommitted(ctx) {
136				return
137			}
138			fmt.Fprintln(os.Stderr, "[entire] Note: Checkpoints were pushed to a separate checkpoint remote, but .entire/settings.json does not contain checkpoint_remote in the latest commit. entire.io will not be able to discover these checkpoints until checkpoint_remote is committed and pushed in .entire/settings.json.")
139		})
140	}
