187	// tryPushSessionsCommon attempts to push the sessions branch.
188	func tryPushSessionsCommon(ctx context.Context, remote, branchName string) (pushResult, error) {
189		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
190		defer cancel()
191	
192		// Use --no-verify to prevent recursive hook calls
193		cmd := CheckpointGitCommand(ctx, remote, "push", "--no-verify", remote, branchName)
194	
195		output, err := cmd.CombinedOutput()
196		outputStr := string(output)
197		if err != nil {
198			// Check if it's a non-fast-forward error (we can try to recover)
199			if strings.Contains(outputStr, "non-fast-forward") ||
200				strings.Contains(outputStr, "rejected") {
201				return pushResult{}, errors.New("non-fast-forward")
202			}
203			return pushResult{}, fmt.Errorf("push failed: %s", outputStr)
204		}
205	
206		return parsePushResult(outputStr), nil
207	}
