333	// getMergeBase returns the merge base hash of two commits, or an error if they
334	// have no common ancestor.
335	func getMergeBase(ctx context.Context, repoPath, hashA, hashB string) (plumbing.Hash, error) {
336		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
337		defer cancel()
338	
339		cmd := exec.CommandContext(ctx, "git", "merge-base", hashA, hashB)
340		cmd.Dir = repoPath
341		output, err := cmd.Output()
342		if err != nil {
343			return plumbing.ZeroHash, fmt.Errorf("git merge-base failed: %w", err)
344		}
345	
346		return plumbing.NewHash(strings.TrimSpace(string(output))), nil
347	}
348	
349	// collectCommitsSince returns non-merge commits reachable from tip but not from
350	// exclude, ordered oldest-first in topological order.
351	func collectCommitsSince(ctx context.Context, repo *git.Repository, repoPath string, tip, exclude plumbing.Hash) ([]*object.Commit, error) {
352		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
353		defer cancel()
354	
355		// cherryPickOnto computes each commit's delta against its first parent, so
356		// replaying merge commits would incorrectly re-apply changes that arrived via
357		// non-first-parent history. Limit the replay set to non-merge commits.
358		cmd := exec.CommandContext(ctx, "git", "rev-list", "--reverse", "--topo-order", "--no-merges", exclude.String()+".."+tip.String())
359		cmd.Dir = repoPath
360		output, err := cmd.Output()
361		if err != nil {
362			return nil, fmt.Errorf("git rev-list failed: %w", err)
363		}
364	
365		lines := strings.Fields(string(output))
366		if len(lines) > MaxCommitTraversalDepth {
367			return nil, fmt.Errorf("commit chain exceeded %d commits; aborting rebase", MaxCommitTraversalDepth)
368		}
369	
370		commits := make([]*object.Commit, 0, len(lines))
371		for _, line := range lines {
372			hash := plumbing.NewHash(line)
373			commit, commitErr := repo.CommitObject(hash)
374			if commitErr != nil {
375				return nil, fmt.Errorf("failed to get commit %s: %w", hash, commitErr)
376			}
377			if len(commit.ParentHashes) > 1 {
378				continue
379			}
380			commits = append(commits, commit)
381		}
382	
383		return commits, nil
384	}
385	
386	// startProgressDots prints dots to w every second until the returned stop function
387	// is called. The stop function prints the given suffix and a newline.
388	func startProgressDots(w io.Writer) func(suffix string) {
389		done := make(chan struct{})
390		stopped := make(chan struct{})
391		go func() {
392			defer close(stopped)
393			ticker := time.NewTicker(time.Second)
394			defer ticker.Stop()
395			for {
396				select {
397				case <-done:
398					return
399				case <-ticker.C:
400					fmt.Fprint(w, ".")
401				}
402			}
403		}()
404		return func(suffix string) {
405			close(done)
406			<-stopped // Wait for goroutine to finish before writing suffix
407			fmt.Fprintln(w, suffix)
408		}
409	}
410	
411	// isURL returns true if the target looks like a URL rather than a git remote name.
412	func isURL(target string) bool {
413		return strings.Contains(target, "://") || strings.Contains(target, "@")
414	}
415	
416	// createMergeCommitCommon creates a merge commit with multiple parents.
417	func createMergeCommitCommon(repo *git.Repository, treeHash plumbing.Hash, parents []plumbing.Hash, message string) (plumbing.Hash, error) {
418		authorName, authorEmail := GetGitAuthorFromRepo(repo)
419		now := time.Now()
420		sig := object.Signature{
421			Name:  authorName,
422			Email: authorEmail,
423			When:  now,
424		}
425	
426		commit := &object.Commit{
427			TreeHash:     treeHash,
428			ParentHashes: parents,
429			Author:       sig,
430			Committer:    sig,
431			Message:      message,
432		}
433	
434		obj := repo.Storer.NewEncodedObject()
435		if err := commit.Encode(obj); err != nil {
436			return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
437		}
438	
439		hash, err := repo.Storer.SetEncodedObject(obj)
440		if err != nil {
441			return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
442		}
443	
444		return hash, nil
445	}
